"""Publish measured run evidence, without calling a sampled record an optimum."""
from pathlib import Path
from zoneinfo import ZoneInfo
import base64, datetime, html, json
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from jump_monitor_data import ROOT, atomic, read, lines
from export_jump_monitor_motion import export

T=ROOT/'results/controlled_broad_jump/ppo_full_overnight_v31'
R=ROOT/'results/controlled_broad_jump/overnight_review_2026_11_25'
OUT=ROOT/'deliverables/jump_optimization_review/2026-11-25'
C={'bg':'#0d141d','panel':'#131f2b','text':'#e7eef4','muted':'#a5b8ca','green':'#72d6bb','orange':'#f0af74','red':'#ec8691','blue':'#7caedb'}

def figures(summary,episodes,updates,cases):
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'figure.facecolor':C['bg'],'axes.facecolor':C['bg'],'text.color':C['text'],'axes.labelcolor':C['muted'],'xtick.color':C['muted'],'ytick.color':C['muted'],'axes.edgecolor':'#344454','grid.color':'#344454'})
    train=[r for r in episodes if r['kind']=='train'];x=np.arange(1,len(train)+1);d=np.array([r['contact_distance_m']if r['stable']else np.nan for r in train]);best=np.maximum.accumulate(np.where(np.isfinite(d),d,-np.inf));best[~np.isfinite(best)]=np.nan
    fig,axes=plt.subplots(3,1,figsize=(11,9),sharex=True,gridspec_kw={'height_ratios':[2,1,1]})
    axes[0].scatter(x,d,s=3,c=C['blue'],alpha=.18,label='Stable sampled jump / 0.5 ms')
    axes[0].plot(x,best,c=C['orange'],lw=2,label='Best sample / failed refined replay')
    axes[0].plot([r['training_episodes']for r in updates],[r['mean_policy_distance_m']if r['mean_policy_stable']else np.nan for r in updates],c=C['green'],lw=1.3,label='Deterministic mean policy / 0.5 ms')
    axes[0].axhline(summary['initial_coarse_m'],c=C['muted'],ls='--',lw=1,label='Initial mean / 0.5 ms')
    axes[0].set(ylabel='Supported distance (m)',ylim=(1.7,2.16));axes[0].legend(loc='lower right',fontsize=8,frameon=False,ncol=2)
    blocks=[train[i:i+512]for i in range(0,len(train),512)];bx=np.cumsum([len(b)for b in blocks]);success=[np.mean([r['stable']for r in b])*100 for b in blocks];rewards=[np.mean([r['reward']for r in b])for b in blocks]
    axes[1].plot(bx,success,c=C['blue'],marker='.',lw=1.5);axes[1].set(ylabel='Sample stability (%)',ylim=(0,100))
    axes[2].plot(bx,rewards,c=C['green'],marker='.',lw=1.5);axes[2].set(ylabel='Mean sampled reward',xlabel='Actual PPO training episodes')
    for ax in axes:ax.grid(alpha=.35);ax.spines[['top','right']].set_visible(False)
    fig.suptitle('11,180 rollouts: higher expected reward, no verified distance gain',fontsize=15)
    fig.tight_layout();fig.savefig(OUT/'learning_review.png',dpi=160);plt.close(fig)

    fig,axes=plt.subplots(1,2,figsize=(11,4.5),gridspec_kw={'width_ratios':[1.3,1]})
    labels={'initial_500us':'Initial','best_500us':'Best sample / coarse','best_125us':'Same best / refined','mean_125us':'Final mean / refined'}
    colors=[C['blue'],C['orange'],C['red'],C['green']]
    for label,color in zip(labels,colors):
        z=np.load(R/label/'control_motion.npz');t=z['times'];to=cases[label]['mechanics'];source=read(R/label/'control_summary.json');mask=t>=source['takeoff_s'];y=z['com'][mask,2];forward=-z['com'][mask,1]
        axes[0].plot(forward,y,c=color,lw=1.8,label=labels[label]);axes[0].scatter([forward[-1]],[y[-1]],s=20,c=color)
        native=z['physics_times_s'];fz=z['physics_force_world_N'][:,2]/(87*9.80665);stride=max(1,len(native)//2200)
        axes[1].plot(native[::stride]-source['touchdown_s'],fz[::stride],c=color,lw=1,alpha=.85)
    axes[0].set(xlabel='Forward world position (m)',ylabel='COM height (m)',title='Nearly identical flight; different recovery');axes[0].legend(frameon=False,fontsize=8)
    axes[1].set(xlabel='Time from touchdown (s)',ylabel='Native vertical GRF (BW)',xlim=(-.08,.35),title='Contact-model output, not muscle force')
    for ax in axes:ax.grid(alpha=.3);ax.spines[['top','right']].set_visible(False)
    fig.tight_layout();fig.savefig(OUT/'refinement_review.png',dpi=160);plt.close(fig)

    names=cases['initial_500us']['joint_names'];groups=[('Trunk',['flex_extension']),('Hip',['hip_flexion_r','hip_flexion_l']),('Knee',['knee_angle_r','knee_angle_l']),('Ankle',['ankle_angle_r','ankle_angle_l']),('Shoulder',['shoulder_elv_r','shoulder_elv_l']),('Elbow',['elbow_flexion_r','elbow_flexion_l'])]
    fig,ax=plt.subplots(figsize=(10,4.6));y=np.arange(len(groups))
    for j,(label,color,title)in enumerate([('initial_500us',C['blue'],'Initial'),('best_500us',C['orange'],'Best sample / coarse'),('mean_500us',C['green'],'Final mean')]):
        usage=np.array(cases[label]['net_torque_capacity_fraction']);values=[max(usage[names.index(n)]for n in stems)*100 for _,stems in groups];ax.barh(y+(j-1)*.24,values,height=.21,color=color,label=title)
    ax.axvline(100,color=C['red'],lw=1,ls='--');ax.set(yticks=y,yticklabels=[g[0]for g in groups],xlabel='Peak absolute net joint torque / fixed virtual torque cap (%)',xlim=(0,106));ax.invert_yaxis();ax.legend(frameon=False,loc='lower right');ax.grid(axis='x',alpha=.3);ax.spines[['top','right']].set_visible(False);ax.set_title('Shared virtual actuator ceiling; not a measured human strength profile',pad=15);fig.tight_layout();fig.savefig(OUT/'torque_capacity_review.png',dpi=160);plt.close(fig)

def main():
    OUT.mkdir(parents=True,exist_ok=True);replays=read(R/'replay_results.json');assert replays is not None,'Wait for native replays to finish.';cases={r['label']:r for r in replays};updates=lines(T/'updates.jsonl');live=read(T/'live_training.json');definition=read(R/'review_definition.json');verification=read(ROOT/'results/controlled_broad_jump/two_metre_initial_solution_verified/verification.json')
    episodes=sorted([dict(r,worker=f.parent.name)for f in T.glob('worker_*/episodes.jsonl')for r in lines(f)],key=lambda r:r.get('finished_at',0));train=[r for r in episodes if r['kind']=='train'];best=max((r for r in train if r['stable']),key=lambda r:r['contact_distance_m']);best_index=next(i+1 for i,r in enumerate(train)if r is best)
    group=[cases[f'best_{us}us']for us in [500,250,125]];robust_best=all(r['stable']and r['mechanics']['status']=='passed'and r['actuator_ledger']['status']=='passed'for r in group)
    mean_group=[cases[f'mean_{us}us']for us in [500,250,125]];robust_mean=all(r['stable']and r['mechanics']['status']=='passed'and r['actuator_ledger']['status']=='passed'for r in mean_group)
    summary=dict(conclusion='Not a demonstrated optimal posture under physiological strength constraints.',initial_verified_finest_m=verification['cases'][-1]['valid_contact_distance_m'],initial_coarse_m=cases['initial_500us']['distance_m'],best_training_sample_coarse_m=best['contact_distance_m'],best_sample_passed_refinement=robust_best,final_mean_coarse_m=cases['mean_500us']['distance_m'],final_mean_finest_m=cases['mean_125us']['distance_m'],final_mean_passed_refinement=robust_mean,training_episodes=live['training_episodes'],physical_rollouts=live['physical_rollouts'],logged_optimizer_rounds=len(updates),optimizer_epochs=live['optimizer_epochs'],training_success_fraction=np.mean([r['stable']for r in train]),last_1000_success_fraction=np.mean([r['stable']for r in train[-1000:]]),first_1000_success_fraction=np.mean([r['stable']for r in train[:1000]]),best_found_at_training_episode=best_index,best_found_at_KST=datetime.datetime.fromtimestamp(best['finished_at'],ZoneInfo('Asia/Seoul')).isoformat(),hours_without_a_new_training_best=(live['heartbeat']-best['finished_at'])/3600,actor_std_first=updates[0]['std'],actor_std_last=updates[-1]['std'],mean_action_max_abs=definition['mean_action_max_abs'],final_mean_change_vs_initial_pct=(cases['mean_500us']['distance_m']/cases['initial_500us']['distance_m']-1)*100,virtual_capacity_definition=definition['capacity'],physiological_muscle_strength_model=False,global_or_local_optimality_proved=False,replay_cases=replays)
    summary['episodes_in_completed_updates']=updates[-1]['training_episodes'];summary['final_partial_rollout_not_used_in_update']=live['training_episodes']-updates[-1]['training_episodes'];summary['best_sample_max_virtual_torque_usage_fraction']=max(cases['best_500us']['net_torque_capacity_fraction']);summary['best_sample_any_torque_cap_saturated']=any(v>0 for v in cases['best_500us']['fraction_physics_samples_at_capacity'])
    phase=read(R/'phase_objective_review.json')
    if phase:summary['phase_objective_revision']=phase
    atomic(OUT/'analysis.json',summary);figures(summary,episodes,updates,cases)
    # A frozen, self-contained evidence artifact. Works directly from a local file.
    motion_names=['initial_500us','best_500us','best_125us','mean_125us','best_250us','mean_500us','mean_250us'];motions=[]
    for label in motion_names:motions.append(export(R/label,target=OUT/f'{label}_motion.json',label=label))
    def png(name):return 'data:image/png;base64,'+base64.b64encode((OUT/name).read_bytes()).decode()
    titles={'initial_500us':'Initial / 0.5 ms','best_500us':'Best sample / 0.5 ms','best_125us':'Same best / 0.125 ms','best_250us':'Same best / 0.25 ms','mean_125us':'Final mean / 0.125 ms','mean_500us':'Final mean / 0.5 ms','mean_250us':'Final mean / 0.25 ms'}
    rows=''
    for label in ['initial_500us','best_500us','best_250us','best_125us','mean_500us','mean_250us','mean_125us']:
        r=cases[label];distance=f"{r['distance_m']:.3f} m"if r['stable']else'착지 후 넘어짐';rows+=f"<tr><td>{titles[label]}</td><td class=\"{'good'if r['stable']else'bad'}\">{distance}</td><td>{r['first_heel_m']:.3f} m</td><td>{r['mechanics']['status']} / {r['actuator_ledger']['status']}</td></tr>"
    cap=definition['capacity']['joint_torque_limits_Nm'];torque_rows=''.join(f'<tr><td>{html.escape(k)}</td><td>{v:.1f} Nm</td><td>{100*cases["best_500us"]["net_torque_capacity_fraction"][cases["best_500us"]["joint_names"].index(k)]:.1f}%</td></tr>'for k,v in cap.items())
    page=PAGE.replace('__SUMMARY__',json.dumps(summary,ensure_ascii=False)).replace('__MOTIONS__',json.dumps(motions,ensure_ascii=False)).replace('__TITLES__',json.dumps(titles)).replace('__ROWS__',rows).replace('__TORQUES__',torque_rows)
    for key,name in [('__LEARNING__','learning_review.png'),('__REFINEMENT__','refinement_review.png'),('__CAPACITY__','torque_capacity_review.png')]:page=page.replace(key,png(name))
    page=page.replace('__SUCCESS__',f'{summary["training_success_fraction"]*100:.1f}').replace('__PLATEAU__',f'{summary["hours_without_a_new_training_best"]:.1f}').replace('__DELTA__',f'{summary["final_mean_change_vs_initial_pct"]:.2f}').replace('__CAPMAX__',f'{summary["best_sample_max_virtual_torque_usage_fraction"]*100:.1f}')
    if phase:
        section='''<section class="panel" style="border-color:#72d6bb"><h2>목표 수정: 도약 성능과 착지 회복은 별개입니다</h2><p><b>이전의 “재계산 탈락” 판정은 현재 회복 제어까지 포함한 완전 동작에 대한 판정입니다. 도약 자체가 비현실적이거나 사람이 착지할 수 없다고 증명한 것이 아닙니다.</b></p><p>최고 후보는 세 시간 간격에서 공중 COM·각운동량 검사와 접촉 전 관절 범위 검사를 통과했습니다. 첫 발 접촉 순간의 뒤꿈치 위치는 <b>2.1243 / 2.1263 / 2.1282 m</b>로, 전체 차이가 약 <b>3.94 mm</b>입니다. 이 도약·접촉 후보는 보존해 평가합니다. 이후 회복 성공 여부와 기존 2.117 m 점수는 별도 지표로 남깁니다.</p><div class="split"><div><p><b>현재 있는 발 기능:</b> 각 발에 뒤꿈치·앞발을 포함한 여섯 접촉점, 네이티브 마찰·반력, 발목 토크에 의한 간접 압력중심(COP) 조절, 착지 후 제한된 접촉 반응 제어.</p><p><b>현재 빠진 기능:</b> 능동 MTP 관절·발가락 굽힘 토크, 학습된 회복 동작과 발 옮기기, 3차원 균형 회복. 따라서 현재 제어기의 넘어짐을 인간의 회복 한계로 단정하지 않습니다.</p></div><div><p><b>이 작업의 1차 목표:</b> 동일한 힘 한계에서 힘의 시간 변화와 관절 동작의 타이밍을 조절해 도약·첫 접촉 거리를 최대화합니다. 이후의 고정된 기립 회복 실패만으로 1차 점수를 지우지 않습니다.</p><p><b>별도 회복 평가:</b> 착지 속도·각운동량·발 지지와 COP를 기록합니다. 첫 접촉 거리만으로 공식 기록이나 실제 착지 가능성을 확정하지도 않습니다. 발가락 누락이 이번 실패의 유일한 원인인지는 아직 판단되지 않았습니다.</p></div></div><p class="muted">기존 학습은 자세·타이밍을 PD 제어로 추종한 결과이며, 개별 근육 힘의 시간곡선을 직접 학습한 결과는 아닙니다. 근육 힘→모멘트암→관절 토크→접촉 반력→운동의 연결을 명시해야 합니다. 지면반력을 별도의 자유로운 외력으로 주입하지 않습니다.</p><p class="foot">참고: <a href="https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0268634">Yamauchi &amp; Koyama, 2022</a>는 18명의 한발 점프에서 앞발 관절 고정이 수평 도약 거리와 COP 이동에 영향을 주는 것을 관찰했습니다. 이 연구는 추진 구간의 근거이며, 본 모델의 착지 실패가 발가락 추가만으로 해결된다는 근거는 아닙니다.</p></section>'''
        page=page.replace('<section class="panel"><h2>동일한 모델, 서로 다른 결과</h2>',section+'<section class="panel"><h2>동일한 모델, 서로 다른 결과</h2>')
        page=page.replace('최고 표본은 시간 간격을 줄이면 착지에 실패했습니다. 최종 평균 정책도 초기해의 거리를 넘지 못했습니다.','최고 표본은 시간 간격을 줄여도 도약·첫 접촉 거리는 거의 같지만, 현재 회복 제어로는 넘어집니다. 도약 성능과 착지 회복을 분리해야 합니다. 최종 평균 정책도 초기해의 거리를 넘지 못했습니다.')
        page=page.replace('0.25 / 0.125 ms 착지 실패 → 확정 기록 제외','0.25 / 0.125 ms 회복 실패 · 도약 성능은 별도 보존')
        page=page.replace('2.117 m의 향상, 자세의 국소·전역 최적성, 특정 사람의 근력을 반영한 최대 점프 거리.','회복을 포함한 2.117 m의 성공 기록, 자세의 국소·전역 최적성, 특정 사람의 근력을 반영한 최대 점프 거리. 도약·첫 접촉 성능의 개선 가능성은 따로 평가합니다.')
        page=page.replace('착지의 접촉·제어 민감도를 낮추고, 후보 평가에 여러 시간 간격과 작은 조건 변화를 포함해야 합니다. 이후 최고 표본을 재현할 수 있는 초기화에서 다시 정책을 비교하는 순서가 맞습니다.','도약의 힘·타이밍 평가와 회복 점수를 분리하고, 힘의 시간 변화까지 탐색할 제어 인터페이스를 구성합니다. 발의 COP·접촉·회복 제어는 별도로 보완하고, 여러 시간 간격의 도약 지표를 함께 확인합니다.')
    (OUT/'index.html').write_text(page,encoding='utf-8');atomic(ROOT/'results/jump_overnight/review.json',dict(report=str(OUT/'index.html'),best_sample_refinement_status='passed'if robust_best else'rejected',best_sample_rejection_scope='Full current-controller recovery, not takeoff/flight performance',launch_replay_status='passed'if phase and phase['precontact_dynamics_passed_all_replays']else'not_assessed',first_contact_heel_spread_m=phase['heel_projection_spread_m']if phase else None,final_mean_refinement_status='passed'if robust_mean else'rejected',initial_finest_m=summary['initial_verified_finest_m'],best_sample_coarse_m=summary['best_training_sample_coarse_m'],final_mean_finest_m=summary['final_mean_finest_m'],converged=False))
    print('OVERNIGHT_REVIEW_READY',OUT/'index.html');print(json.dumps({k:v for k,v in summary.items()if k not in ['replay_cases','virtual_capacity_definition']},indent=2))

PAGE='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jump optimization / Overnight review</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0d141d;color:#e7eef4;font:15px/1.7 system-ui,sans-serif}main{max-width:1260px;margin:auto;padding:34px 24px}h1{font-size:30px;font-weight:600;line-height:1.35;margin:8px 0 20px}h2{font-size:20px;font-weight:550;margin:0 0 15px}p{margin:12px 0}.tag{font-size:11px;letter-spacing:2px;color:#72d6bb}.lead{font-size:18px;max-width:970px}.muted,small{color:#a5b8ca}.good{color:#72d6bb}.bad{color:#ec8691}.orange{color:#f0af74}.card,.panel{background:#131f2b;border:1px solid #2c3b4b;border-radius:10px;padding:22px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:25px 0}.value{font-size:30px;letter-spacing:-1px;margin:8px 0}.panel{margin:18px 0}img{display:block;width:100%;margin:18px 0;border-radius:5px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:11px 10px;border-bottom:1px solid #2c3b4b}th{font-weight:450;color:#a5b8ca}.scroll{overflow:auto}.split{display:grid;grid-template-columns:1fr 1fr;gap:20px}.motions{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}canvas{display:block;width:100%;height:290px;background:#0d1722;border-radius:7px}select,button{background:#1a2a3b;color:#e7eef4;border:1px solid #3c5064;border-radius:5px;padding:7px 10px}select{width:100%;margin-bottom:9px}.controls{display:flex;gap:14px;align-items:center;margin:16px 0}input{accent-color:#72d6bb;flex:1}.verdict{border-left:3px solid #ec8691;padding-left:18px}.math{font-family:Consolas,monospace;color:#f0af74}a{color:#72d6bb}.foot{font-size:12px;color:#a5b8ca;margin-top:25px}li{margin:7px 0}@media(max-width:850px){.metrics{grid-template-columns:repeat(2,1fr)}.motions,.split{grid-template-columns:1fr}canvas{height:300px}main{padding:24px 16px}}
</style></head><body><main><div class="tag">BIOMECHANICS / 2026-11-25 / ACTUAL RUN EVIDENCE</div><h1>자세는 최적화됐는가?</h1><p class="lead verdict"><b>아직 그렇다고 판단하기 어렵습니다.</b> 고정된 가상 관절 토크 한계 안에서 더 멀리 뛴 표본은 찾았지만, 최고 표본은 시간 간격을 줄이면 착지에 실패했습니다. 최종 평균 정책도 초기해의 거리를 넘지 못했습니다.</p>
<div class="metrics"><div class="card"><small>검사를 통과한 초기해 / 0.125 ms</small><div class="value good">2.002 m</div><small>세 시간 간격에서 안정 착지</small></div><div class="card"><small>학습 중 최고 표본 / 0.5 ms</small><div class="value orange">2.117 m</div><small class="bad">0.25 / 0.125 ms 착지 실패 → 확정 기록 제외</small></div><div class="card"><small>최종 평균 정책 / 0.125 ms</small><div class="value">1.963 m</div><small>안정 착지 · 초기해보다 짧음</small></div><div class="card"><small>PPO 학습용 표본 생성</small><div class="value">11,180회</div><small>완료 업데이트에 11,136회 사용 · 마지막 44회 미사용</small></div></div>
<section class="panel"><h2>동일한 모델, 서로 다른 결과</h2><p class="muted">실제 네이티브 분절 위치를 그대로 재생합니다. 모든 화면은 같은 축척의 고정 측면 뷰입니다. 주황색은 질량중심이고, 공중 궤적은 착지 후 표시됩니다. 개별 근육 장력 컨투어는 이 제어 모델에 아직 연결되지 않았습니다.</p><div class="motions"><div><select id="sel0"></select><canvas id="c0"></canvas><small id="caption0"></small></div><div><select id="sel1"></select><canvas id="c1"></canvas><small id="caption1"></small></div><div><select id="sel2"></select><canvas id="c2"></canvas><small id="caption2"></small></div></div><div class="controls"><button id="play">Pause</button><select id="speed" style="width:100px"><option value="1">1×</option><option value=".5" selected>0.5×</option></select><input id="scrub" type="range" min="0" max="1000" value="0"><span id="time">0.00 s</span></div></section>
<section class="panel"><h2>근력은 어떻게 적용했나?</h2><div class="split"><div><p>학습에서 고정한 것은 <b>11개 내부 관절의 순 토크 진폭 한계</b>입니다. 좌우 고관절·무릎·발목, 어깨·팔꿈치와 체간의 가상 액추에이터가 동일하게 고정된 한계 프로필 아래에서, 43개 자세·타이밍 변수를 함께 조절했습니다.</p><p class="math">torque cap = 1.5 × initial-motion peak |net torque|</p><p>순 토크에는 명시적 P/피드포워드 토크와 속도 피드백의 부호 있는 합이 들어갑니다. 이 수치는 <b>특정 사람의 최대 근력이나 근육군별 최대 장력으로 보정된 값이 아닙니다.</b></p><p>최고 표본에서도 가장 높은 피크 사용률은 가상 한계의 <b>__CAPMAX__%</b>였고, 한계에 걸려 잘린 샘플은 없었습니다. 이번 해는 가상 토크 상한을 소진한 해도 아닙니다. 다만 이 비율을 사람의 여유 근력으로 환산할 수는 없습니다.</p></div><div><p><b>반영된 조건</b>: 질량·관성, 관절 가동 범위, 중력·마찰·발 접촉, 고정 토크 한계, 자세에 따른 실제 힘과 모멘트의 변화.</p><p><b>현재 없는 조건</b>: 개별 근육의 단면적 기반 최대 힘, 근육별 힘–길이·힘–속도 관계, 근육들 사이의 힘 분배 및 공유 능력, 실측한 개인별 근력 곡선.</p><p>따라서 “같은 가상 토크 조건에서 자세를 바꾼 비교”까지는 가능하지만, “사람의 근력을 고려한 최적 자세”로 해석할 근거는 부족합니다.</p></div></div><img src="__CAPACITY__" alt="Net torque versus fixed virtual capacity"><details><summary>전체 관절 한계와 최고 표본의 피크 사용률</summary><div class="scroll"><table><tr><th>Generalized joint</th><th>Fixed virtual cap</th><th>Peak / cap</th></tr>__TORQUES__</table></div><small>사용률은 동작 전체의 |순 관절 토크| 피크 기준이며, 근육 활성률·근력 사용률 또는 근육 장력이 아닙니다. 좌우와 동작 위상별 최대 시점도 다릅니다.</small></details></section>
<section class="panel"><h2>학습 로그가 보여주는 것</h2><img src="__LEARNING__" alt="Actual overnight PPO learning curves"><div class="split"><div><p>전체 학습 표본의 안정 착지 비율은 <b>__SUCCESS__%</b>였습니다. 처음 1,000회는 47.2%, 마지막 1,000회는 57.9%로, 평균 보상과 착지 성공률은 올라갔습니다. 최고 표본 이후 약 <b>__PLATEAU__시간</b> 동안 더 긴 유효 표본은 나오지 않았습니다.</p><p>그러나 정체가 곧 최적성의 증거는 아닙니다. 탐색은 초기해 주변의 제한된 범위였고, 다른 초기화·탐색 범위·보상에서는 다른 해가 나올 수 있습니다.</p></div><div><p>최종 평균 정책은 동일한 0.5 ms 기준으로 초기해보다 <b>__DELTA__%</b> 짧았습니다. 학습된 정책이 최고 표본을 재현하도록 수렴한 상태는 아닙니다.</p><p>현재 보상은 안정 착지 시 거리, 실패 시 음수입니다. 따라서 PPO는 성공한 한 번의 최대 거리와 달리 <b>탐색 분포의 기대 보상</b>을 학습합니다. 최고 표본과 평균 정책은 반드시 분리해야 합니다.</p></div></div></section>
<section class="panel"><h2>시간 간격을 줄여 재계산한 결과</h2><div class="scroll"><table><thead><tr><th>Case</th><th>Supported distance</th><th>First heel contact</th><th>Mechanics / energy ledger</th></tr></thead><tbody>__ROWS__</tbody></table></div><img src="__REFINEMENT__" alt="Flight and contact timestep comparison"><p>최고 표본의 이륙 속도와 첫 접촉 거리는 재계산에서도 거의 같았습니다. 차이는 주로 <b>충격을 흡수하고 자세를 회복하는 구간</b>에 나타났습니다. 현재 착지 제어가 미세한 접촉 변화에 민감하다는 증거입니다.</p><p class="muted">최고 표본의 추진 피크 지면반력은 약 3.26 BW, 착지 피크는 0.5 ms에서 약 12.84 BW였습니다. 착지 피크는 접촉 강성·시간·제어에 민감한 모델 출력이며 실측한 사람의 부하로 검증되지 않았습니다. 이 값을 근육 힘과 혼동하지 않습니다. 에너지·운동방정식 일치는 사람의 동작 현실성 검증과도 별개입니다.</p></section>
<section class="panel"><h2>현재 결론과 다음 우선순위</h2><ol><li><b>확정할 수 있는 결과:</b> 약 2.00 m의 초기해와 약 1.96 m의 최종 평균 정책은 세 시간 간격에서 안정적으로 재생됩니다.</li><li><b>확정할 수 없는 결과:</b> 2.117 m의 향상, 자세의 국소·전역 최적성, 특정 사람의 근력을 반영한 최대 점프 거리.</li><li><b>우선 보완:</b> 착지의 접촉·제어 민감도를 낮추고, 후보 평가에 여러 시간 간격과 작은 조건 변화를 포함해야 합니다. 이후 최고 표본을 재현할 수 있는 초기화에서 다시 정책을 비교하는 순서가 맞습니다.</li></ol></section>
<p class="foot">모델 178 cm / 87 kg · RK4 · 강체 분절 · 강체 발 · 네이티브 중력·마찰·접촉 · 시상면 제약 · 인위적인 루트 힘·이륙 충격량·공중 COM 경로 없음.<br>Source: results/controlled_broad_jump/ppo_full_overnight_v31, overnight_review_2026_11_25 · Code: build_overnight_jump_review.py, replay_overnight_jump_review.py · <a href="https://mujoco.readthedocs.io/en/stable/computation/index.html">MuJoCo computation</a> (해석기 설명; 본 모델의 사람 대상 검증 출처가 아님)</p>
</main><script>
const SUMMARY=__SUMMARY__,MOTIONS=__MOTIONS__,TITLES=__TITLES__;let selected=[0,1,2],playing=true,clock=0,last=performance.now();const E=id=>document.getElementById(id);for(let k=0;k<3;k++){const s=E('sel'+k);s.innerHTML=MOTIONS.map((m,i)=>`<option value="${i}">${TITLES[m.label]}</option>`).join('');s.value=selected[k];s.onchange=()=>{selected[k]=+s.value;clock=0}}E('play').onclick=()=>{playing=!playing;E('play').textContent=playing?'Pause':'Play'};E('scrub').oninput=()=>{playing=false;E('play').textContent='Play';clock=+E('scrub').value/1000*6};function draw(k,t){const m=MOTIONS[selected[k]],el=E('c'+k),r=el.getBoundingClientRect(),d=devicePixelRatio||1;el.width=r.width*d;el.height=r.height*d;const c=el.getContext('2d');c.scale(d,d);const w=r.width,h=r.height,scale=Math.min((w-35)/3.5,(h-48)/2.05),gy=h-29;const P=v=>[18+(-v[1]+.35)*scale,gy-v[2]*scale];let i=m.t.findIndex(x=>x>=t);if(i<0)i=m.t.length-1;c.font='10px system-ui';c.fillStyle='#a5b8ca';c.strokeStyle='#2c3b4b';c.beginPath();c.moveTo(7,gy);c.lineTo(w-7,gy);c.stroke();for(let x=0;x<=3;x+=.5){const p=P([0,-x,0]);c.textAlign='center';c.fillText(x.toFixed(1),p[0],gy+17)}if(t>=m.touchdown_s){const path=m.com.filter((v,j)=>m.t[j]>=m.takeoff_s&&m.t[j]<=m.touchdown_s),n=Math.ceil(path.length*Math.min(1,(t-m.touchdown_s)/.7));c.strokeStyle='#f0af74';c.setLineDash([3,3]);c.beginPath();path.slice(0,n).forEach((v,j)=>j?c.lineTo(...P(v)):c.moveTo(...P(v)));c.stroke();c.setLineDash([])}const xyz=m.xyz[i];for(let j=0;j<xyz.length;j++){if(m.parents[j]<0)continue;c.strokeStyle=m.names[j].endsWith('_l')?'#5e7a8e':'#bbd0dc';c.lineWidth=m.names[j]==='torso'?12:m.names[j].includes('femur')?7:4;c.lineCap='round';c.beginPath();c.moveTo(...P(xyz[j]));c.lineTo(...P(xyz[m.parents[j]]));c.stroke()}const head=m.names.indexOf('head');c.fillStyle='#bbd0dc';c.beginPath();c.arc(...P(xyz[head]),.09*scale,0,2*Math.PI);c.fill();c.fillStyle='#f0af74';c.beginPath();c.arc(...P(m.com[i]),3,0,2*Math.PI);c.fill();c.textAlign='left';c.fillStyle='#a5b8ca';c.fillText(`GRF ${m.grf[i].toFixed(2)} BW`,10,18);if(!m.stable&&t>m.t.at(-1)){c.fillStyle='#ec8691';c.font='bold 14px system-ui';c.fillText('FAILED RECOVERY',10,40)}const good=m.stable;E('caption'+k).className=good?'good':'bad';E('caption'+k).textContent=good?m.valid_distance_m.toFixed(3)+' m · stable supported contact':'Rejected · first heel '+m.first_heel_m.toFixed(3)+' m';}function tick(now){const dt=(now-last)/1000;last=now;if(playing)clock=(clock+dt*(+E('speed').value))%6.5;const t=Math.min(clock,6);E('time').textContent=t.toFixed(2)+' s';E('scrub').value=t/6*1000;for(let k=0;k<3;k++)draw(k,t);requestAnimationFrame(tick)}requestAnimationFrame(tick);
</script></body></html>'''

if __name__=='__main__':main()
